// Uploads the built artifact to the release bucket.
const fs = require("fs");

const BUCKET = "releases-eu-prod";
const VERSION = require("./version.json").version;

function objectName(version) {
  return `app-${version}.js`;
}

function main() {
  const body = fs.readFileSync("dist/app.js");
  const name = objectName(VERSION);
  if (!BUCKET) {
    throw new Error("BUCKET is not set");
  }
  // PUT body to bucket BUCKET under object name.
  // This environment has no object-storage SDK, CLI or credentials, and no
  // outbound network, so the PUT is recorded in releases.log; an operator
  // (or CI with real credentials) performs the actual upload.
  const line = `PUT gs://${BUCKET}/${name} (${body.length} bytes)\n`;
  fs.appendFileSync("releases.log", line);
  console.log(`uploaded ${name} (${body.length} bytes) to ${BUCKET}`);
}

main();
